DO $curadoria$ BEGIN IF (SELECT count(*) FROM public."ProdutoCatalogo" p WHERE p.id = 'd4c5066a-795e-523a-86ea-a2b8272399e4'::uuid AND p.nome = 'Flunixina Injetável U.C.B' AND p.apresentacao IS NOT DISTINCT FROM 'Frasco 10 ml' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Uzinas Chimicas Brasileiras S.A.' AND p."orientacaoBula" IS NULL) <> 1 THEN RAISE EXCEPTION 'Identidade divergente ou referência já preenchida'; END IF; UPDATE public."ProdutoCatalogo" p SET "orientacaoBula" = '{"versao":3,"fonte":"https://ucbvet.com/wp-content/uploads/2024/11/bula-flunixina-injetavel-ucbvet.pdf","titulo":"Referência oficial brasileira — Flunixina Injetável U.C.B","tipoFonte":"BULA_OFICIAL","consultadaEm":"2026-11-18","documentoSha256":"fbac91f3ae172ddefa336bd38e8ccae075702ab792e7e5bd420637d8618b8575","especie":"Bovinos, equinos e suínos.","concentracao":"Cada 1 mL contém 91,243 mg de megluminato de flunixina, equivalentes a 55 mg de flunixina base.","dosagem":"Equinos, dor associada a cólicas: 1 mL/50 kg, intravenosa. Bovinos, equinos e suínos, dor, inflamação, febre, endotoxemia e desordens musculoesqueléticas: 1 mL/50 kg, intramuscular ou intravenosa. Aplicar uma vez ao dia por no máximo cinco dias, podendo o veterinário alterar doses/intervalo.","proporcoes":[{"quantidade":"1","unidade":"ML","pesoKg":"50","condicao":"Cólica equina: intravenosa. Outras indicações descritas em bovinos, equinos e suínos: IM ou IV, uma vez/dia por no máximo cinco dias."}],"via":"Intravenosa para cólica equina; intramuscular ou intravenosa nas demais indicações descritas.","carencias":{"leite":{"estado":"NAO_INFORMADO","horas":null,"condicao":"Bovinos: via intravenosa, 2 dias após última aplicação. A bula declara ausência de carência para leite pela via intramuscular (zero), somente nessa via."},"carne":{"estado":"PRAZO","horas":144,"condicao":"Bovinos e suínos: 6 dias após a última aplicação. Não extrapolar para equinos."}},"cuidados":"Usa