DO $curadoria$ BEGIN IF (SELECT count(*) FROM public."ProdutoCatalogo" p WHERE p.id = 'c88a2f7f-7189-5ecd-84b3-84ab585a6987'::uuid AND p.nome = 'Mastizone V.S. ( Vaca Seca )' AND p.apresentacao IS NOT DISTINCT FROM 'Seringa 10 g' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Uzinas Chimicas Brasileiras S.A.' AND p."orientacaoBula" IS NULL) <> 1 THEN RAISE EXCEPTION 'Identidade divergente ou referência já preenchida'; END IF; UPDATE public."ProdutoCatalogo" p SET "orientacaoBula" = '{"versao":3,"fonte":"https://ucbvet.com/wp-content/uploads/2026/06/bula-mastizone-vs.pdf","titulo":"Referência oficial brasileira — Mastizone V.S. ( Vaca Seca )","tipoFonte":"BULA_OFICIAL","consultadaEm":"2026-11-18","documentoSha256":"f8d94e238f8ec9e50c694f61e04befa77f6e060b3337ab144be4b3c99fecb6f1","especie":"Bovinos: vacas no período seco.","concentracao":"Cada seringa de 10 g contém sulfato de gentamicina 400 mg; veículo q.s.p. 10 g.","dosagem":"Uma seringa de 10 g por quarto mamário, dose única após a última ordenha da lactação. Tratar os quatro quartos. Ordenhar completamente, higienizar e secar os tetos, infundir e massagear de baixo para cima. A bula baseia a carência em período seco médio de 36 dias.","proporcoes":[],"via":"Exclusivamente intramamária.","carencias":{"leite":{"estado":"NAO_INFORMADO","horas":null,"condicao":"Bovinos: 3 dias após o parto, com estudo baseado em período seco médio de 36 dias; não contar a partir da aplicação. Não usar durante lactação."},"carne":{"estado":"PRAZO","horas":384,"condicao":"Bovinos: 16 dias após a última aplicação."}},"cuidados":"Não administrar em vacas lactantes, outras espécies, animais hipersensíveis ou com insuficiência renal. Tratar somente no início da secagem. Não associar com furosemida ou anfotericina B; cautela com relaxantes musculares. Não tocar a extremidade da cânula; fazer desinfecção ao final.","camposFonte":{"concentracao":{"url":"https://ucbvet.com/wp-content/