DO $curadoria$ BEGIN IF (SELECT count(*) FROM public."ProdutoCatalogo" p WHERE p.id = 'eec39be3-57f2-560a-89be-5f11228cfc8e'::uuid AND p.nome = 'Ocitocina Forte U.C.B' AND p.apresentacao IS NOT DISTINCT FROM 'Frasco 5 ml' AND (SELECT f.nome FROM public."FabricanteProduto" f WHERE f.id = p."fabricanteId") IS NOT DISTINCT FROM 'Uzinas Chimicas Brasileiras S.A.' AND p."orientacaoBula" IS NULL) <> 1 THEN RAISE EXCEPTION 'Identidade divergente ou referência já preenchida'; END IF; UPDATE public."ProdutoCatalogo" p SET "orientacaoBula" = '{"versao":3,"fonte":"https://ucbvet.com/wp-content/uploads/2024/11/bula-ocitocina-forte.pdf","titulo":"Referência oficial brasileira — Ocitocina Forte U.C.B","tipoFonte":"BULA_OFICIAL","consultadaEm":"2026-11-18","documentoSha256":"a68323db5644b8333f7947b743dcaf72a2b193e7bc3017737d5654ed85823090","especie":"Bovinos, equinos, suínos, caprinos e ovinos.","concentracao":"Ocitocina sintética 10 UI por mL.","dosagem":"Vacas e éguas: SC ou IM 2–5 mL; IV 1–2,5 mL; epidural 1,5–3 mL. Porcas: SC ou IM 1–3 mL; IV 0,5–1,5 mL. Ovelhas e cabras: SC ou IM 0,5–1 mL; IV 0,25–0,75 mL. A indicação determina a via: insuficiência contrátil durante parto, SC; retenção de leite, IM e ordenhar 5–10 minutos depois; prolapsos uterinos recentes, epidural em vacas/éguas associada a anestésico; retenção de placenta/hemorragia pós-parto/atonia, IM, IV ou epidural em vacas/éguas. IV deve ser lenta.","proporcoes":[],"via":"Subcutânea, intramuscular, intravenosa ou epidural conforme espécie e indicação descritas.","carencias":{"leite":{"estado":"NAO_INFORMADO","horas":null,"condicao":"Prazo não informado na fonte oficial consultada; desconhecimento não é zero."},"carne":{"estado":"NAO_INFORMADO","horas":null,"condicao":"Prazo não informado na fonte oficial consultada; desconhecimento não é zero."}},"cuidados":"Aplicação IV lenta. Nos casos de insuficiência contrátil, a bula orienta reavaliar após 20 minutos e proceder segundo recomendação veterinária. Conservar fechado